package com.amdocs.telecom.security; import java.security.SecureRandom; import java.util.concurrent.*; public class CaptchaGenerator{private final SecureRandom r=new SecureRandom();private final ConcurrentMap<String,String> vals=new ConcurrentHashMap<>();public String[] create(){String id=Long.toHexString(r.nextLong()),v=String.format("%04d",r.nextInt(10000));vals.put(id,v);return new String[]{id,v};}public boolean verify(String id,String value){String v=vals.remove(id);return v!=null&&v.equals(value);} }
